 'Experience'=>['professional_experience'=>'Professional experience — Role / Company or industry / Dates / Responsibilities / Technologies','project_experience'=>'Selected project experience — Project / Industry / Role / Overview / Contribution / Technologies','architecture_experience'=>'Architecture & engineering experience','delivery_experience'=>'Delivery experience','leadership_experience'=>'Leadership experience','industry_experience'=>'Relevant industry experience'],
