if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$companyId=(int)($_POST['company_id']??0);$internalName=trim(mb_substr((string)($_POST['internal_name']??''),0,180));$primaryRole=trim(mb_substr((string)($_POST['primary_role']??''),0,180));$seniority=(string)($_POST['seniority']??'Senior');$allowedSeniorities=['Mid','Senior','Lead','Architect'];$status=(string)($_POST['profile_status']??'draft');$allowedStatuses=['draft','verified','shareable'];$verification=array_values(array_intersect(array_keys($verificationLabels),(array)($_POST['verification']??[])));
