  if($profile){db()->prepare('UPDATE engineering_profiles SET company_id=?,internal_name=?,primary_role=?,seniority=?,profile_status=?,data_json=?,content=? WHERE id=?')->execute([$companyId?:null,$internalName,$primaryRole,$seniority,$status,json_encode($profileData,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$html,$id]);}else{$id=uuid_v4();db()->prepare('INSERT INTO engineering_profiles (id,company_id,created_by,profile_id,internal_name,primary_role,seniority,profile_status,data_json,content) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$id,$companyId?:null,$user['id'],$profileCode,$internalName,$primaryRole,$seniority,$status,json_encode($profileData,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$html]);}
  flash('success','Το Engineering Profile αποθηκεύτηκε. Το προσωπικό όνομα παραμένει μόνο μέσα στο CRM.');redirect_to('profile.php?id='.urlencode($id));
 }
 $data=array_merge($data,$_POST);$data['verification']=$verification;
}
